chapters.example:
{
  "permissions": {
    "defaultMode": "default"
  }
}

{
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash|PowerShell",
        "hooks": [{"type": "command", "command": "echo pre >> \"${CLAUDE_PROJECT_DIR}/hook-log.txt\""}]
      }
    ],
    "PostToolUse": [
      {
        "matcher": "Bash|PowerShell",
        "hooks": [{"type": "command", "command": "echo post >> \"${CLAUDE_PROJECT_DIR}/hook-log.txt\""}]
      }
    ],
    "Stop": [
      {
        "hooks": [{"type": "command", "command": "echo stop >> \"${CLAUDE_PROJECT_DIR}/hook-log.txt\""}]
      }
    ]
  }
}

{
  "hooks": {
    "SessionStart": [
      {
        "hooks": [{"type": "command", "command": "echo \"Briefing: the deploy freeze starts on Friday.\"; echo start >> \"${CLAUDE_PROJECT_DIR}/hook-log.txt\""}]
      }
    ],
    "UserPromptSubmit": [
      {
        "hooks": [{"type": "command", "command": "echo \"Ticket note: the current ticket is T-77.\"; echo prompt >> \"${CLAUDE_PROJECT_DIR}/hook-log.txt\""}]
      }
    ]
  }
}

{
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash|PowerShell",
        "hooks": [
          {
            "type": "command",
            "command": "bash \"${CLAUDE_PROJECT_DIR}\"/.claude/hooks/safety-check.sh"
          }
        ]
      }
    ]
  }
}

{
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Write|Edit",
        "hooks": [
          {
            "type": "command",
            "command": "python",
            "args": ["${CLAUDE_PROJECT_DIR}/.claude/hooks/secure-diff-gate.py"]
          }
        ]
      }
    ]
  }
}

{
  "mcpServers": {
    "rooms": {
      "command": "python3",
      "args": ["server.py"]
    }
  }
}

{
  "mcpServers": {
    "big": {
      "command": "python3",
      "args": ["big_server.py"]
    }
  }
}

{
  "permissions": {
    "allow": ["mcp__rooms__list_rooms"],
    "deny": ["mcp__rooms__door_code"]
  }
}

{
  "permissions": {
    "allow": ["Edit", "Bash(git *)", "PowerShell(git *)"],
    "ask": ["Bash(git commit *)", "PowerShell(git commit *)"],
    "deny": ["Edit(config.txt)"]
  }
}

{
  "permissions": {
    "allow": ["Edit(.claude/**)", "Edit(.git/**)", "Edit(notes.txt)"]
  }
}

{
  "disableSkillShellExecution": true
}

{
  "permissions": {
    "allow": [
      "Edit",
      "Bash(python -m unittest*)", "Bash(python3 -m unittest*)",
      "PowerShell(python -m unittest*)", "PowerShell(python3 -m unittest*)"
    ],
    "deny": ["Edit(test_calc.py)"]
  }
}

claude -p "Categorize this issue" \
  --output-format json \
  --json-schema '{
    "type":"object",
    "properties":{
      "category":{"type":"string","enum":["bug","feature","docs"]},
      "severity":{"type":"integer","minimum":1,"maximum":5}
    },
    "required":["category","severity"]
  }'

{
  "hooks": {
    "SessionStart": [
      {
        "hooks": [
          {"type": "command", "command": "echo ran >> \"${CLAUDE_PROJECT_DIR}/hook-ran.txt\""}
        ]
      }
    ]
  }
}
